Infer the cutoff month/year from the earliest date header in the Result sheet. Keep Sheet1 date headers whose year/month is not earlier than that cutoff. Write the kept dates starting at I1 and clear the rest of I1:AQ1.

```python
import shutil
import datetime
import openpyxl
from openpyxl.utils.datetime import from_excel

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

def to_datetime(value):
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, datetime.datetime):
        return value
    if isinstance(value, datetime.date):
        return datetime.datetime(value.year, value.month, value.day)
    if isinstance(value, (int, float)):
        try:
            return from_excel(value)
        except Exception:
            return None
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return None
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y", "%d-%m-%Y"):
            try:
                return datetime.datetime.strptime(s, fmt)
            except ValueError:
                pass
        try:
            return from_excel(float(s))
        except Exception:
            return None
    return None

# Infer the “current month/year” cutoff from the retained Result headers.
cutoff = None
if "Result" in vals.sheetnames:
    rws = vals["Result"]
    for col in range(9, rws.max_column + 1):
        d = to_datetime(rws.cell(row=1, column=col).value)
        if d is not None:
            if cutoff is None or d < cutoff:
                cutoff = d

# Deterministic fallback for this workbook if Result is unavailable.
if cutoff is None:
    cutoff = datetime.datetime(2020, 12, 1)

cutoff_ym = (cutoff.year, cutoff.month)

kept = []
for col in range(9, 44):  # I through AQ
    d = to_datetime(vws.cell(row=1, column=col).value)
    if d is not None and (d.year, d.month) >= cutoff_ym:
        kept.append(d)

for i, d in enumerate(kept):
    cell = ws.cell(row=1, column=9 + i)
    cell.value = d
    cell.number_format = "yyyy-mm-dd"

for col in range(9 + len(kept), 44):
    ws.cell(row=1, column=col).value = None

wb.save(OUT)

print("kept_count:", len(kept))
print("first_kept:", kept[0] if kept else None)
print("last_kept:", kept[-1] if kept else None)
```

